int square(int n)
{
    return n * n;
}

int main(void)
{
    int a = square(5);
    printf("%d\n", a);
    return 0;
}

double avg(int a, int b)
{
    return (a + b) / 2.0;
}

int main(void)
{
    printf("%.1f\n", avg(3, 4));
    return 0;
}

void bump(int n)
{
    n = n + 1;
}

int main(void)
{
    int x = 5;
    bump(x);
    printf("%d\n", x);
    return 0;
}
